package com.bank.fs;

import java.util.*;
import java.util.logging.Logger;

abstract class FileSystemNode {
    final String name; String permissions = "rw-r--r--";
    FileSystemNode(String name) { this.name = name; }
    abstract long size();                         // Composite operation
    abstract void print(String indent);
}

class File extends FileSystemNode {
    private final long bytes;
    File(String name, long bytes) { super(name); this.bytes = bytes; }
    long size() { return bytes; }                 // leaf
    void print(String indent) { Logger.getLogger("FS").info(indent + name + " (" + bytes + "B)"); }
}

class Directory extends FileSystemNode {
    final List<FileSystemNode> children = new ArrayList<>();
    Directory(String name) { super(name); }
    void add(FileSystemNode node) { children.add(node); }
    long size() { return children.stream().mapToLong(FileSystemNode::size).sum(); } // recurse
    void print(String indent) {
        Logger.getLogger("FS").info(indent + name + "/");
        children.forEach(c -> c.print(indent + "  "));
    }
    FileSystemNode resolve(String path) {          // path resolution
        String[] parts = path.replaceFirst("^/", "").split("/");
        FileSystemNode current = this;
        for (String part : parts) {
            if (!(current instanceof Directory d)) return null;
            current = d.children.stream().filter(c -> c.name.equals(part)).findFirst().orElse(null);
            if (current == null) return null;
        }
        return current;
    }
    void move(FileSystemNode node, Directory target) {
        if (isDescendant(node, target)) throw new IllegalArgumentException("Cannot move into own descendant");
        children.remove(node); target.add(node);
    }
    private boolean isDescendant(FileSystemNode node, Directory target) {
        return node == target; // simplified cycle guard
    }
}

class FileSystemService {
    long totalSize(Directory root) { return root.size(); }
}

public class FsDemo {
    public static void main(String[] args) {
        Directory rajesh = new Directory("rajesh");
        Directory tax = new Directory("tax");
        rajesh.add(new File("statement.pdf", 2048));
        tax.add(new File("2025.pdf", 4096));
        rajesh.add(tax);
        rajesh.print("");
        Logger.getLogger("FS").info("Total size = " + rajesh.size() + " bytes");
        FileSystemNode found = rajesh.resolve("/tax/2025.pdf");
        Logger.getLogger("FS").info("Resolved: " + (found != null ? found.name : "not found"));
    }
}
